/* Five-week A1 learning flow. All teaching content is available within the app. */
window.GERMAN_SPRINT_UI=function(api){
 'use strict';
 const {getState,save,frame,intro,e,icon,arrow,navigate,startLesson,lessonById,speak,toast}=api;
 const C=window.GERMAN_COURSE,S=window.GERMAN_SPRINT,K=window.KLEIN_CORE;
 let openDay=null,openBlocks=null,listenId='',listenChoice=null,listenFeedback='',recallFeedback='',wordFeedback='',wordHelp=false,retrievalFeedback='',pdfURL=null,pdfName='',pdfChapter=1;
 const state=()=>getState();
 const day=n=>S.days.find(d=>d.number===Number(n))||S.next(state());
 const current=()=>day(location.hash.split('/')[1]);
 const record=d=>state().sprint.days[d.number]??=S.entry();
 const chapter=n=>C.book.chapters[n-1];
 const links=(url,label)=>`<a class="text-link small" href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>`;
 const tick=(kind,d,label,checked,i)=>`<label class="sprint-check"><input type="checkbox" data-sprint="${kind}" data-day="${d.number}" data-value="${i}" ${checked?'checked':''}><span>${e(label)}</span></label>`;
 const chipTitles=['Study & recall','Reading','Listening','Writing','Speaking'];
 const chips=d=>S.statuses(state(),d).map((done,i)=>`<span class="${done?'complete':''}">${done?'✓ ':''}${chipTitles[i]}</span>`).join('');
 const wordLabel=w=>[w.article,w.de].filter(Boolean).join(' ');
 const wordAnswer=w=>wordLabel(w);
 const routeDay=route=>{const [kind,id]=String(route).split('/');if(kind==='book-pages')return window.GERMAN_BOOK.dayFor(Number(id));if(['day','speaking','vocabulary','recall'].includes(kind))return day(id).number;const l=lessonById(id);return l?.planDay||S.next(state()).number;};
 function trackRoute(route){if(/^(lesson|reading|writing|listening|speaking|vocabulary|recall|day|book-pages)\//.test(route)){state().sprint.resume={route,day:routeDay(route)};save();}}
 function go(to){trackRoute(to);navigate(to);}
 function continueDay(d){state().sprint.startedAt??=new Date().toISOString();const next=S.nextTask(state(),d);state().sprint.resume={...next,day:d.number};save();if(next.kind==='lesson')startLesson(next.lessonId);else go(next.route);}
 function resumeCourse(){
  const saved=state().sprint.resume;
  if(saved && saved.day && !S.data(state(),saved.day).completedAt && saved.route && saved.route!==location.hash.slice(1)){
   const [kind,id]=saved.route.split('/');
   const complete=kind==='lesson'&&state().progress[id]?.completedAt||kind==='reading'&&state().skills.reading[id]?.correct.length===3||kind==='listening'&&state().sprint.listening[id]?.correct.length===3||kind==='book-pages'&&state().sprint.bookPages[id]?.done||kind==='writing'&&state().skills.writing[id]?.passed;
   if(!complete){state().sprint.startedAt??=new Date().toISOString();save();go(saved.route);return;}
   continueDay(day(saved.day));return;
  }
  continueDay(S.next(state()));
 }
 function primary(d,label){const task=S.nextTask(state(),d);return `<button class="btn" data-action="day-start" data-day="${d.number}">${e(label||task.title)} ${arrow()}</button>`;}
 const clock=t=>{const seconds=t.endsAt?Math.max(0,Math.ceil((t.endsAt-Date.now())/1000)):t.remaining;return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');};
 function timer(){const t=state().sprint.timer;return `<section class="focus-session panel"><div><p class="eyebrow">One small session</p><strong id="focus-clock">${clock(t)}</strong><span>${t.mode==='break'?'Rest your eyes. Move a little.':'25 minutes of focus, then a 5-minute break.'}</span></div><div><button class="btn light" data-action="timer-toggle">${t.endsAt?'Pause':'Start timer'}</button><button class="text-link tiny" data-action="timer-reset">Reset</button><button class="text-link tiny" data-action="timer-break">${t.mode==='break'?'Focus session':'5-minute break'}</button></div></section>`;}
 function home(){const d=S.next(state()),done=S.days.filter(x=>S.data(state(),x.number).completedAt).length,task=S.nextTask(state(),d);return frame(`${intro('Your five-week German course','A1. One day at a time.','The full book’s learning scope, explained and practised here.')}<section class="sprint-hero"><div><p class="eyebrow">${done===35?'Planned course completed':d.phase+' · Day '+d.number+' of 35'}</p><h2>${e(d.title)}</h2><p>${e(d.goal)}</p><div class="skill-chips">${chips(d)}</div><div class="sprint-hero-actions"><button class="btn" data-action="sprint-start">${state().sprint.startedAt?'Continue':'Start'} ${arrow()}</button><a class="btn light" href="#day/${d.number}">Today’s plan</a></div><p class="next-caption">Next: ${e(task.title)}</p></div><div class="day-art" aria-hidden="true"><span>DAY</span><strong>${String(d.number).padStart(2,'0')}</strong><span>OF 35</span></div></section><div class="sprint-stats"><div><strong>${done}<small> / 35</small></strong><span>study days finished</span></div><div><strong>About 3 hours</strong><span>focused study / day, split into small sessions</span></div><div><strong>2 → 3 → 1</strong><span>learn twice · practise three times · blind try</span></div></div>${timer()}<div class="sprint-shortcuts"><a class="panel" href="#plan">${icon('path',24)}<strong>Your five-week route</strong><span>24 teaching days, 4 chapter reviews, 7 application and check days.</span></a><a class="panel" href="#coverage">${icon('blocks',24)}<strong>What A1 covers</strong><span>Every book goal linked to its teaching and practice.</span></a><a class="panel" href="#theory">${icon('book',24)}<strong>Chapters & theory</strong><span>Explanations, complete reference tables and contextual vocabulary.</span></a></div>${Object.keys(state().sprint.legacyPlans||{}).length?'<details class="study-note"><summary>Your previous progress is kept</summary><p>The original lessons, drafts and settings remain saved. Earlier 21-day records are archived under that plan; they have not been treated as completion of different five-week activities. Export your complete progress from Settings at any time.</p></details>':''}<details class="study-note"><summary>How the five-week plan works</summary><p>Budget about 180 focused minutes a day, plus breaks. This is a planning estimate: pause whenever you need and resume the same study day. Calendar gaps do not add overdue work.</p><p>Lessons explain the book’s A1 learning goals using original examples and tasks. Your daily plan includes the original textbook pages, with a place to save your answers. Listening uses a German voice provided by your browser/device; publisher and Goethe recordings are available for additional listening.</p><p>Completion records your work. Delayed recall records later retrieval. Speaking and open messages use explicit self-checks; they are not automatically certified. The final week provides fresh practical tasks and links to official A1 practice.</p></details>`);}
 function plan(){return frame(`${intro('35 days · Five weeks','Your course, in view.','Study three small lessons on a teaching day. Combine them in reading, listening, writing and speech.')}<div class="course-notice"><strong>About 3 focused hours per day + breaks</strong><span>Days follow your progress, not the calendar. Save & pause whenever needed.</span></div>${[0,1,2,3,4].map(w=>`<section class="plan-week"><div class="section-head"><div><p class="eyebrow">Week ${w+1}</p><h2>${['Meet people & find your way','Food, family & plans','Work, health & home','Past events, shopping & travel','Use it, repair it, check it'][w]}</h2></div></div><div class="plan-grid">${S.days.slice(w*7,w*7+7).map(d=>{const done=S.data(state(),d.number).completedAt,active=S.next(state()).number===d.number;return `<a class="plan-day ${done?'done':''} ${active?'current':''}" href="#day/${d.number}" ${active?'aria-current="step"':''}><span>${done?'✓ Day '+d.number:'Day '+d.number}</span><strong>${e(d.title)}</strong><small>${e(d.phase)} · ${d.lessonIds.length} ${d.lessonIds.length===1?'mission':'lessons'}</small></a>`;}).join('')}</div></section>`).join('')}<a class="text-link small" href="#coverage">Inspect the full A1 topic map ↗</a>`);}
 function lessonLinks(ids,kind='lesson'){return `<div class="day-lesson-list">${ids.map(id=>{const l=lessonById(id),done=kind==='reading'?state().skills.reading[id]?.correct.length===3:kind==='writing'?state().skills.writing[id]?.passed:kind==='listening'?state().sprint.listening[id]?.correct.length===3:!!state().progress[id]?.completedAt;return `<div><span>${icon(done?'check':kind==='writing'?'name':kind==='listening'?'speaker':'book',17)}${e(l.title)}</span>${kind==='lesson'?`<button class="btn light small-btn" data-action="start" data-id="${id}">${done?'Repeat':'Start'}</button>`:`<a class="btn light small-btn" href="#${kind}/${id}">${done?'Practised':'Open'}</a>`}</div>`;}).join('')}</div>`;}
 function examples(d){const models=d.lessonIds.slice(0,2).map(lessonById);if(models.length===1)models.push(models[0]);return `<details class="daily-examples"><summary>Two explained writing models</summary>${models.map((l,i)=>{const m=i===1&&models[0]===l?l.cards[1].examples[1]:{de:l.writing.model,en:'Use this fixed scenario to inspect the sentence pattern.',why:l.writing.explanation};return `<article><p class="eyebrow">Example ${i+1}</p><p lang="de">${e(m.de)}</p><p>${e(m.en)}</p><small>Why it works: ${e(m.why)}</small></article>`;}).join('')}</details>`;}
 function draftBox(d){const v=record(d);return `<p>${e(d.writingPrompt)}</p><p>Use today’s patterns to give concrete details. Make a first attempt, check it, close the examples, then write your revised version.</p><label class="eyebrow" for="day-draft">Your saved German message</label><textarea id="day-draft" data-day="${d.number}" rows="6" class="type-answer writing-answer" placeholder="Write your own message here…">${e(v.draft)}</textarea><p class="tiny"><span id="day-word-count">${S.words(v.draft)}</span> words · at least ${d.minWords} for this study task · saved as you type</p>${['I addressed the situation and included concrete details.','I checked the verb, word order and capital letters on nouns.','I closed the models and wrote my revised message from memory.'].map((t,i)=>tick('writing',d,t,v.writingChecks.includes(i),i)).join('')}<p class="writing-scope">Your self-check records your review, not an automatic grammar score. Guided writing above checks its specified pattern and listed alternatives. Ask a teacher or fluent speaker to review a fresh message when possible.</p>`;}
 function speakingBody(d){const v=record(d),ls=d.speakingIds.map(lessonById);return `<p>Say your answer aloud before typing notes. First use the models, then repeat with the models closed. Ask for repetition when something is unclear.</p>${ls.map(l=>`<section class="speaking-task"><h3>${e(l.title)}</h3><ol class="simple-steps">${l.speaking.prompts.map(p=>`<li>${e(p)}</li>`).join('')}</ol><details class="daily-examples"><summary>Two explained spoken models</summary>${l.speaking.examples.map(x=>`<article><p lang="de">${e(x.de)}</p><p>${e(x.en)}</p><small>${e(x.why)}</small><button class="text-link tiny" data-action="speak" data-text="${e(x.de)}">${icon('speaker',13)}Hear the model</button></article>`).join('')}</details><ul class="simple-steps">${l.speaking.rubric.map(p=>`<li>${e(p)}</li>`).join('')}</ul></section>`).join('')}<label class="eyebrow" for="speaking-notes">Your speaking evidence</label><textarea id="speaking-notes" data-day="${d.number}" class="type-answer writing-answer" rows="4" placeholder="Save a phrase you said, a correction, or feedback from your partner…">${e(v.speakingNotes)}</textarea><p class="tiny">Save at least six words describing what you said or need to improve. Notes stay on this device.</p>${['I answered the prompts aloud twice, including once without models.','I asked a question and practised a request for repetition or clarification.','I recorded what worked and repeated one difficult part.'].map((t,i)=>tick('speaking',d,t,v.speaking.includes(i),i)).join('')}<p class="writing-scope">Speaking evidence is self-reported or partner-reviewed. The website does not grade pronunciation.</p>`;}
 function dailyBlind(d){const v=record(d),i=[0,1,2].find(i=>!v.retrieval.includes(i));return `<section class="panel day-retrieval"><p class="eyebrow">Finish from memory · ${v.retrieval.length} / 3</p><h2>Close the notes. Try it blind.</h2>${i===undefined?'<p>Three retrieval tasks answered correctly.</p>':`<p>${e(S.retrieval(d)[i].prompt)}</p><label class="sr-only" for="day-blind">Your answer in German</label><input id="day-blind" class="type-answer" autocomplete="off" spellcheck="false" placeholder="Answer from memory…"><button class="btn light" data-action="day-blind" data-day="${d.number}">Check answer</button>${retrievalFeedback?`<p role="status" class="tiny">${e(retrievalFeedback)}</p>`:''}`}<button class="btn finish-day" data-action="finish-day" data-day="${d.number}" ${S.ready(state(),d)?'':'disabled'}>${v.completedAt?'Day finished ✓':'Finish Day '+d.number} ${icon('check',16)}</button>${!S.ready(state(),d)?`<details class="remaining-tasks"><summary>What remains before finishing?</summary><ul class="simple-steps">${S.missing(state(),d).map(t=>`<li>${e(t)}</li>`).join('')}</ul></details>`:''}</section>`;}
 function dayPage(){const d=current();if(openDay!==d.number){openDay=d.number;openBlocks=null;}const done=S.statuses(state(),d),vocab=S.wordsForDay(state(),d),review=S.reviewTasks(state(),d),bodies=[`<p>Two teaching passes with four explained examples → three drills → reading → guided writing → a fresh blind answer.</p>${lessonLinks(d.lessonIds)}<div class="theory-actions"><a class="btn light" href="#vocabulary/${d.number}">Vocabulary · ${vocab.filter(w=>w.passed).length}/${vocab.length}</a><a class="btn light" href="#recall/${d.number}">Later recall · ${review.length} remaining</a></div>`,`<p>Read the complete texts here. Each has three meaning questions and an optional translation. Look for the people, place, time and purpose.</p>${lessonLinks(d.readingIds,'reading')}${window.GERMAN_BOOK.assignment(d,state())}`,`<ol class="simple-steps"><li>Listen once for the topic, with the transcript closed.</li><li>Listen again for details, then answer three questions.</li><li>Check the transcript afterwards and repeat a short phrase.</li></ol>${lessonLinks(d.readingIds,'listening')}`,`${lessonLinks(d.lessonIds,'writing')}${examples(d)}${draftBox(d)}`,speakingBody(d)];return frame(`${intro(d.phase+' · Day '+d.number+' / 35',d.title,d.goal,`<a class="text-link small" href="#plan">All 35 days</a>`)}<div class="day-overview"><div class="skill-chips">${chips(d)}</div><p>${done.filter(Boolean).length} / 5 study blocks recorded · about 180 focused minutes + breaks</p>${primary(d)}</div>${timer()}<div class="day-blocks" data-day="${d.number}">${bodies.map((html,i)=>`<details class="day-block" data-block="${i}" ${(openBlocks?openBlocks.includes(i):i===done.findIndex(x=>!x))?'open':''}><summary><span class="block-number">${done[i]?'✓':i+1}</span><span><strong>${chipTitles[i]}</strong><small>${[60,25,25,35,35][i]} minute planning block · pause in small sessions</small></span><span class="block-status">${done[i]?'Recorded':'Open'}</span></summary><div class="block-body">${html}</div></details>`).join('')}</div>${dailyBlind(d)}${d.number>=33?finalEvidence(d):''}`);}
 function finalEvidence(d){const v=record(d);return `<section class="panel readiness"><p class="eyebrow">Practice evidence · ${d.number===35?'Final study day':'Fresh application'}</p><h2>Check what you can do with new details.</h2><p>Finishing this mission records activity completion. Use an official A1 practice paper and a conversation partner for an independent check of all four skills.</p>${links(C.book.practice,'Official Goethe A1 papers, audio and speaking practice')}<div class="exam-results"><p>Optional external results: record percentages from an answer key or reviewer. These are entered by you, not verified by this app.</p>${['reading','listening','writing'].map(k=>`<label>${k[0].toUpperCase()+k.slice(1)} · %<input type="number" min="0" max="100" step="1" data-exam="${k}" data-day="${d.number}" value="${e(v.exam[k])}" placeholder="0–100"></label>`).join('')}</div><p>Revisit your weakest patterns using the coverage map. The five-week plan is a course schedule, not an A1 certificate.</p></section>`;}
 function lessonVocabulary(l){if(!l?.vocabulary?.length)return '';return `<details class="lesson-vocabulary"><summary>${l.vocabulary.length} new words · meanings and two examples each</summary><div class="vocabulary-list">${l.vocabulary.map(w=>`<details class="vocabulary-entry"><summary><strong lang="de">${e(wordLabel(w))}</strong><span>${e(w.en)}</span></summary>${w.plural?`<p class="tiny">Plural: ${e(w.plural)}</p>`:''}${w.forms?`<p class="tiny">Useful forms: ${e(w.forms)}</p>`:''}${w.examples.map(x=>`<p lang="de">${e(x.de)}</p><p class="tiny">${e(x.en)}</p>`).join('')}</details>`).join('')}</div></details>`;}
 function workshops(l){
  if(!l.workshops?.length)return '';
  const answer=q=>'<details class="transfer-check"><summary>'+e(q.prompt)+'</summary><p lang="de">'+e(q.answer)+'</p></details>';
  return '<section class="review-workshops"><h3>Plattform practice</h3>'+l.workshops.map(w=>'<details class="grammar-reference"><summary>'+e(w.title)+'</summary>'+w.passes.map(p=>'<p>'+e(p.body)+'</p>'+p.examples.map(x=>'<p lang="de"><strong>'+e(x.de)+'</strong></p><p>'+e(x.en)+' '+e(x.why)+'</p>').join('')).join('')+'<h4>Try each question before opening its answer</h4>'+w.drills.map(answer).join('')+'<h4>Try a new situation from memory</h4>'+answer(w.blind)+'</details>').join('')+'</section>';
 }
 function theoryCourse(){return frame(`${intro('Theory · All 12 chapters','Learn the whole A1 scope.','Open a chapter for its six full lessons, vocabulary, tables and practice.')}<div class="course-notice"><strong>${C.fullLessons.length} new full lessons and missions</strong><span>Original explanations and exercises for the book’s learning goals. Your earlier 46 lessons remain as extra grammar and phrase practice.</span></div><div class="chapter-grid">${C.book.chapters.map(c=>`<a class="panel chapter-card" href="#textbook/${c.number}"><p class="eyebrow">Chapter ${c.number} · printed pp. ${c.pages.join('–')}</p><h2>${e(c.title)}</h2><p>${e(c.goal)}</p><span>Six full lessons ${arrow()}</span></a>`).join('')}</div><div class="theory-actions"><a class="btn light" href="#appendix">Book appendix</a><a class="btn light" href="#book-pages/0">Read the full book</a><a class="btn light" href="#grammar">Original grammar outline & reference</a><a class="btn light" href="#coverage">Full topic map</a></div>`);}
 function textbook(){const n=Number(location.hash.split('/')[1]);if(n>=1&&n<=12)return textbookChapter(chapter(n));return theoryCourse();}
 function textbookChapter(c){const ls=C.fullLessons.filter(l=>l.chapter===c.number&&l.kind!=='mission');return frame(`${intro('Chapter '+c.number,c.title,c.goal)}<section class="panel"><p>${e(c.focus)}</p><p class="tiny">Source scope: Netzwerk neu A1, printed pp. ${c.pages.join('–')}. The teaching and tasks below are original and available here.</p>${[1,2].map(part=>`<h3>Teaching day ${part}</h3>${lessonLinks(ls.filter(l=>l.part===part).map(l=>l.id))}<div class="theory-actions">${ls.filter(l=>l.part===part).map(l=>`<a class="text-link small" href="#theory/${l.id}">${e(l.title)} · theory</a>`).join('')}</div>`).join('')}<a class="btn light" href="#day/${ls[0].planDay}">Open the daily plan</a></section><section class="panel"><h2>Original book pages</h2><a class="btn light" href="#book-pages/${c.pages[0]}">Read pp. ${c.pages.join('–')} in the course</a></section>`);}
 function coverage(){const rows=C.coverage,counts=C.coverageCategories;return frame(`${intro('A1 coverage · Inspect the teaching','Every goal has a place.','This map links the book’s learning goals to original lessons. It shows content mapping and your activity evidence, not certified mastery.')}<div class="coverage-summary">${counts.map(k=>`<span>${e(k)}<strong>${rows.filter(r=>r.category===k).length}</strong></span>`).join('')}</div>${C.fullScope.chapters.map(c=>`<details class="skill-collection" ${c.number===1?'open':''}><summary><span>Chapter ${c.number} · ${e(c.title)}</span><small>${c.goals.length} goals</small></summary><div class="coverage-goals">${rows.filter(r=>r.chapter===c.number).map(r=>`<article><p class="eyebrow">${e(r.category)}</p><h3>${e(r.title)}</h3>${r.lessonIds.length?r.lessonIds.map(id=>`<a class="text-link small" href="#theory/${id}">${e(lessonById(id).title)}${state().progress[id]?.completedAt?' · completed':''} ↗</a>`).join(''):'<p>Coverage review pending.</p>'}</article>`).join('')}</div></details>`).join('')}<section class="panel"><h2>Beyond this A1 route</h2><p>Full genitive, relative clauses and complete adjective declension remain optional in the grammar reference. They are not prerequisites for finishing this A1 course.</p></section>`);}
 function recall(){const d=current(),tasks=S.reviewTasks(state(),d),t=tasks[0];return frame(`${intro('Later recall · Day '+d.number,'Make earlier learning stick.','These tasks return after 1, 3 and 7 study days. Calendar breaks do not create extra work.')}<section class="panel recall-panel">${t?`<p class="eyebrow">${tasks.length} remaining · from ${e(lessonById(t.lessonId).title)}</p><h2>${e(t.question.prompt)}</h2><label class="sr-only" for="recall-answer">Answer in German</label><input id="recall-answer" class="type-answer" autocomplete="off" spellcheck="false" placeholder="Try from memory…"><div class="theory-actions"><button class="btn" data-action="recall-check" data-day="${d.number}">Check answer</button><a class="text-link small" href="#theory/${t.lessonId}">Relearn this pattern</a></div>${recallFeedback?`<p class="feedback-copy" role="status">${e(recallFeedback)}</p>`:''}`:'<h2>Today’s delayed recall is complete ✓</h2><p>The next review appears on its planned study day.</p>'+primary(d,'Continue today')}<a class="text-link small" href="#day/${d.number}">Back to Day ${d.number}</a></section>`);}
 function vocabulary(){const d=current(),all=S.wordsForDay(state(),d),w=all.find(w=>!w.passed);return frame(`${intro('Vocabulary · Day '+d.number,'Recall the words you just learned.','Nouns include their article. Use the examples for help, then hide them and try again.')}<section class="panel recall-panel"><p class="eyebrow">${all.filter(w=>w.passed).length} / ${all.length} words recalled</p>${w?`<h2>${e(w.en)}</h2><p class="tiny">${w.article?'Write the German noun with der, die or das.':'Write the German word or phrase.'}</p><label class="sr-only" for="vocabulary-answer">German word</label><input id="vocabulary-answer" class="type-answer" autocomplete="off" spellcheck="false" placeholder="German…"><div class="accent-keys">${['ä','ö','ü','ß'].map(x=>`<button data-action="practice-accent" data-for="vocabulary-answer" data-value="${x}">${x}</button>`).join('')}</div><div class="theory-actions"><button class="btn" data-action="vocabulary-check" data-day="${d.number}">Check word</button><button class="btn light" data-action="vocabulary-help">${wordHelp?'Hide and try':'See two examples'}</button></div>${wordHelp?`<div class="word-help"><strong lang="de">${e(wordLabel(w))}</strong>${w.examples.map(x=>`<p lang="de">${e(x.de)}</p><p class="tiny">${e(x.en)}</p>`).join('')}${w.plural?`<p class="tiny">Plural: ${e(w.plural)}</p>`:''}</div>`:''}${wordFeedback?`<p role="status" class="feedback-copy">${e(wordFeedback)}</p>`:''}`:'<h2>Today’s word recall is complete ✓</h2>'+primary(d,'Continue today')}<a class="text-link small" href="#day/${d.number}">Back to Day ${d.number}</a></section>`);}
 function listening(){const id=location.hash.split('/')[1],l=lessonById(id);if(!l?.reading)return frame(`${intro('Listening · Hören','Listen for meaning.','Original short dialogues and announcements for every full lesson.')}<div class="course-notice"><strong>First the topic, then the details</strong><span>Use a German browser/device voice for app passages. Authentic publisher and Goethe recordings are optional additional listening.</span></div>${links(C.book.publisher,'Publisher audio resources')}<div class="skill-collections">${C.book.chapters.map(c=>`<details class="skill-collection" ${c.number===1?'open':''}><summary><span>Chapter ${c.number} · ${e(c.title)}</span></summary>${lessonLinks(C.fullLessons.filter(l=>l.chapter===c.number&&l.kind!=='mission').map(l=>l.id),'listening')}</details>`).join('')}</div>`);
  if(listenId!==id){listenId=id;listenChoice=null;listenFeedback='';}const text=l.listening||l.reading,p=state().sprint.listening[id]||{correct:[]},i=[0,1,2].find(i=>!p.correct.includes(i)),q=text.questions[i];return frame(`${intro('Listening · '+l.title,text.title,'Listen twice with the transcript closed. The listening text is different from your reading task.')}<section class="panel listen-panel"><div class="listen-symbol">${icon('sound',48)}</div><div class="theory-actions"><button class="btn" data-action="speak" data-text="${e(text.text)}">${icon('speaker',17)}Listen · first pass</button><button class="btn light" data-action="speak" data-text="${e(text.text)}">Listen again · details</button></div><p class="tiny">Synthetic German voice from this browser/device. Speed is adjustable in Settings. If no German voice is installed, the app shows a message; no audio result is invented.</p>${q?`<p class="eyebrow">Question ${i+1} / 3</p><h2>${e(q.prompt)}</h2><div class="choices">${q.options.map((x,j)=>`<button class="choice ${listenChoice===j?'selected':''}" data-action="listen-choice" data-value="${j}">${e(x)}</button>`).join('')}</div><button class="btn light" data-action="listen-check" data-id="${id}">Check meaning</button>${listenFeedback?`<p role="status">${e(listenFeedback)}</p>`:''}`:'<h2>Three details understood ✓</h2><button class="btn light" data-action="listen-repeat" data-id="'+id+'">Try the questions again</button>'}<details class="listen-transcript"><summary>Transcript and translation · check afterwards</summary><p lang="de">${e(text.text)}</p><p>${e(text.translation)}</p></details><div class="theory-actions"><button class="btn light" data-action="flow-next">Continue today ${arrow()}</button>${links(C.book.publisher,'Optional publisher recordings')}</div></section>`);}
 function speaking(){const d=current();return frame(`${intro('Speaking · Day '+d.number,'Use the German aloud.','Models, a short exchange and saved performance notes.')}<section class="panel">${speakingBody(d)}<a class="btn light" href="#day/${d.number}">Back to today’s plan</a></section>`);}
 function handle(action,b){const d=day(b.dataset.day),v=record(d);
  if(action==='sprint-start'){resumeCourse();return true;}
  if(action==='flow-next'){continueDay(day(b.dataset.day||routeDay(location.hash.slice(1))));return true;}
  if(action==='day-start'){continueDay(d);return true;}
  if(action==='choose-pdf'){pdfChapter=Number(b.dataset.chapter)||1;document.getElementById('textbook-file').click();return true;}
  if(action==='listen-choice'){listenChoice=Number(b.dataset.value);listenFeedback='';api.render();return true;}
  if(action==='listen-check'){const l=lessonById(b.dataset.id),t=l.listening||l.reading,p=state().sprint.listening[l.id]??={correct:[]},i=[0,1,2].find(i=>!p.correct.includes(i));if(i===undefined)return true;if(listenChoice===null){toast('Choose a meaning first.');return true;}if(listenChoice===t.questions[i].answer){p.correct.push(i);listenFeedback=t.questions[i].explanation;listenChoice=null;save();}else listenFeedback='Not yet. Replay once for this detail, then try another meaning.';api.render();return true;}
  if(action==='listen-repeat'){state().sprint.listening[b.dataset.id]={correct:[]};listenChoice=null;listenFeedback='';save();api.render();return true;}
  if(action==='recall-check'){const t=S.reviewTasks(state(),d)[0],input=document.getElementById('recall-answer');if(!t||!input?.value.trim()){toast('Try an answer first.');return true;}const prev=state().sprint.recall[t.key]||{attempts:0};const passed=K.isCorrect(t.question,input.value);state().sprint.recall[t.key]={...prev,passed,attempts:prev.attempts+1,lastAt:Date.now()};recallFeedback=passed?'Recalled correctly. '+(t.question.explanation||'Try the next pattern.'):'This pattern needs another look. Open its explanation, compare the examples, then return for a fresh attempt.';save();api.render();return true;}
  if(action==='vocabulary-help'){wordHelp=!wordHelp;api.render();return true;}
  if(action==='vocabulary-check'){const w=S.wordsForDay(state(),d).find(w=>!w.passed),input=document.getElementById('vocabulary-answer');if(!w||!input?.value.trim()){toast('Try a German word first.');return true;}if(wordHelp){toast('Hide the examples before checking your recall.');return true;}const prior=state().sprint.vocabulary[w.id]||{attempts:0},passed=K.normalise(input.value)===K.normalise(wordAnswer(w));state().sprint.vocabulary[w.id]={...prior,passed,attempts:prior.attempts+1,lastAt:Date.now()};wordFeedback=passed?'Correct. Try the next word.':'Check the word’s spelling'+(w.article?' and its article.':'.')+' You can open its two examples before trying again.';save();api.render();return true;}
  if(action==='practice-accent'){const input=document.getElementById(b.dataset.for);if(input){const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.value=input.value.slice(0,start)+b.dataset.value+input.value.slice(end);input.focus();input.setSelectionRange(start+1,start+1);}return true;}
  if(action==='day-blind'){const i=[0,1,2].find(i=>!v.retrieval.includes(i)),input=document.getElementById('day-blind');if(i===undefined)return true;if(!input?.value.trim()){toast('Try a German answer first.');return true;}if(K.isCorrect(S.retrieval(d)[i],input.value)){v.retrieval.push(i);retrievalFeedback='Correct. Continue with the next recall task.';save();}else retrievalFeedback='Not yet. Check that you included the requested details. You can revisit the relevant lesson, then return to try without notes.';api.render();return true;}
  if(action==='finish-day'){if(S.finish(state(),d.number)){save();toast('Day '+d.number+' recorded. Take a break; your place is saved.');go(d.number===35?'day/35':'today');}return true;}
  if(action.startsWith('timer-')){const t=state().sprint.timer;if(action==='timer-toggle'){if(t.endsAt){t.remaining=Math.max(0,Math.ceil((t.endsAt-Date.now())/1000));t.endsAt=null;}else{if(!t.remaining)t.remaining=t.mode==='break'?300:1500;t.endsAt=Date.now()+t.remaining*1000;}}else if(action==='timer-reset'){t.endsAt=null;t.remaining=t.mode==='break'?300:1500;}else{t.endsAt=null;t.mode=t.mode==='break'?'focus':'break';t.remaining=t.mode==='break'?300:1500;}save();api.render();return true;}
  return false;
 }
 function input(el){if(el.id==='day-draft'||el.id==='speaking-notes'){const d=day(el.dataset.day),v=record(d);if(el.id==='day-draft'){v.draft=el.value.slice(0,16000);v.writingChecks=[];const count=document.getElementById('day-word-count');if(count)count.textContent=S.words(v.draft);document.querySelectorAll('input[data-sprint="writing"]').forEach(x=>x.checked=false);}else{v.speakingNotes=el.value.slice(0,8000);v.speaking=[];document.querySelectorAll('input[data-sprint="speaking"]').forEach(x=>x.checked=false);}v.completedAt=null;const button=document.querySelector('.finish-day');if(button)button.disabled=true;save();return true;}return false;}
 function change(el){if(el.id==='textbook-file'&&el.files?.length){const file=el.files[0];if(!file.name.toLowerCase().endsWith('.pdf')){toast('Choose a PDF.');return true;}if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=URL.createObjectURL(file);pdfName=file.name;go('textbook/'+pdfChapter);api.render();return true;}
  if(el.dataset.exam){const d=day(el.dataset.day),v=record(d),value=el.value;v.exam[el.dataset.exam]=value!==''&&Number.isInteger(Number(value))&&Number(value)>=0&&Number(value)<=100?String(Number(value)):'';save();return true;}
  if(el.dataset.sprint){const d=day(el.dataset.day),v=record(d),kind=el.dataset.sprint,i=Number(el.dataset.value),arr=kind==='writing'?v.writingChecks:v.speaking,at=arr.indexOf(i);if(el.checked&&at<0)arr.push(i);if(!el.checked&&at>=0)arr.splice(at,1);v.completedAt=null;save();api.render();return true;}return false;}
 const picker=()=>'<input id="textbook-file" type="file" accept="application/pdf,.pdf" hidden>';
 function remember(){const wrap=document.querySelector('.day-blocks');if(wrap&&location.hash==='#day/'+wrap.dataset.day){openDay=Number(wrap.dataset.day);openBlocks=[...document.querySelectorAll('.day-block[open]')].map(x=>Number(x.dataset.block));}}
 setInterval(()=>{const t=state().sprint.timer,el=document.getElementById('focus-clock');if(el)el.textContent=clock(t);if(t.endsAt&&t.endsAt<=Date.now()){const focus=t.mode==='focus';t.endsAt=null;t.mode=focus?'break':'focus';t.remaining=focus?300:1500;save();toast(focus?'Focus session complete. Take a five-minute break.':'Break complete. Your next small step is ready.');api.render();}},1000);
 return {workshops,home,plan,dayPage,textbook,listening,handle,input,change,picker,remember,coverage,theoryCourse,recall,vocabulary,speaking,lessonVocabulary,trackRoute};
};
